}

// Default pins
#ifndef PIN_I2S_SCK
  #define PIN_I2S_SCK 14
#endif

#ifndef PIN_I2S_FS
  #if CONFIG_IDF_TARGET_ESP32S2
    #define PIN_I2S_FS 27
  #else
